import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/%E7%A1%85%E5%9F%BA%E6%B5%81%E5%8A%A8-%E5%AE%98%E6%96%B9.C0OazJVO.png",g=JSON.parse('{"title":"【模型接入】硅基流动","description":"","frontmatter":{},"headers":[],"relativePath":"ai/siliconflow.md","filePath":"ai/siliconflow.md","lastUpdated":null}'),l={name:"ai/siliconflow.md"};function d(n,e,r,h,p,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="【模型接入】硅基流动" tabindex="-1">【模型接入】硅基流动 <a class="header-anchor" href="#【模型接入】硅基流动" aria-label="Permalink to &quot;【模型接入】硅基流动&quot;">​</a></h1><p>项目基于 Spring AI + 自己实现的 <code>models/siliconflow</code>，实现 <a href="https://siliconflow.cn/zh-cn/" target="_blank" rel="noreferrer">硅基流动</a> 的接入：</p><table tabindex="0"><thead><tr><th>功能</th><th>模型</th><th>Spring AI 客户端</th></tr></thead><tbody><tr><td>AI 对话</td><td><a href="https://cloud.siliconflow.cn/models?types=chat" target="_blank" rel="noreferrer">对话模型</a></td><td>SiliconFlowChatModel</td></tr><tr><td>AI 绘画</td><td><a href="https://cloud.siliconflow.cn/models?types=to-image" target="_blank" rel="noreferrer">生图模型</a></td><td>SiliconFlowImageModel</td></tr></tbody></table><h2 id="_1-申请密钥" tabindex="-1">1. 申请密钥 <a class="header-anchor" href="#_1-申请密钥" aria-label="Permalink to &quot;1. 申请密钥&quot;">​</a></h2><p>目前硅基流动主要是部署开源模型，所以需要去官网申请 API Key，然后通过 Spring AI 提供的客户端接入。</p><h3 id="_1-1-申请密钥" tabindex="-1">1.1 申请密钥 <a class="header-anchor" href="#_1-1-申请密钥" aria-label="Permalink to &quot;1.1 申请密钥&quot;">​</a></h3><p>① 在 <a href="https://cloud.siliconflow.cn/i/bqIQQ4u4" target="_blank" rel="noreferrer">硅基流动</a> 上，注册一个账号。</p><p>② 在 <a href="https://cloud.siliconflow.cn/account/ak" target="_blank" rel="noreferrer">管理 -&gt; API Key 管理</a> 上，创建一个 API Key 密钥。</p><hr><p>申请完成后，可以在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，进行密钥的配置。只需要填写“密钥”，不需要填写“自定义 API URL”（因为 Spring AI 默认官方地址）。如下图所示：</p><p><img src="'+o+`" alt="官方的密钥配置"></p><h2 id="_2-模型配置" tabindex="-1">2. 模型配置 <a class="header-anchor" href="#_2-模型配置" aria-label="Permalink to &quot;2. 模型配置&quot;">​</a></h2><p>友情提示：</p><p>目前 <code>ai_model</code> 表中，已经预置了一些模型，可以直接使用！！！</p><h3 id="_2-1-ai-对话" tabindex="-1">2.1 AI 对话 <a class="header-anchor" href="#_2-1-ai-对话" aria-label="Permalink to &quot;2.1 AI 对话&quot;">​</a></h3><p>使用 <a href="./chat">《AI 对话》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的聊天模型。</p><p>当前建议优先使用 DeepSeek、Kimi、GLM 的新模型，可以点击 <a href="https://cloud.siliconflow.cn/me/models?types=chat" target="_blank" rel="noreferrer">对话模型</a> 进行查看。</p><p>每个模型标识的 <code>max_tokens</code>（回复数 Token 数）是不同的，整理表格如下：</p><table tabindex="0"><thead><tr><th>模型标识</th><th><code>max_tokens</code> 最大输出 Tokens</th></tr></thead><tbody><tr><td><code>deepseek-ai/DeepSeek-V4-Pro</code></td><td>384000</td></tr><tr><td><code>deepseek-ai/DeepSeek-V4-Flash</code></td><td>65536</td></tr><tr><td><code>moonshotai/Kimi-K2.7-Code</code></td><td>16384</td></tr><tr><td><code>moonshotai/Kimi-K2.6</code></td><td>262144</td></tr><tr><td><code>zai-org/GLM-5.2</code></td><td>262144</td></tr></tbody></table><h3 id="_2-2-ai-绘图" tabindex="-1">2.2 AI 绘图 <a class="header-anchor" href="#_2-2-ai-绘图" aria-label="Permalink to &quot;2.2 AI 绘图&quot;">​</a></h3><p>使用 <a href="./image">《AI 绘图》</a> 时，需要在 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，配置对应的图像模型。</p><p>模型有：<code>Kwai-Kolors/Kolors</code> 等等。</p><h2 id="_3-如何使用" tabindex="-1">3. 如何使用？ <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用？&quot;">​</a></h2><p>① 如果你的项目里需要直接通过 <code>@Resource</code> 注入 SiliconFlowChatModel、SiliconFlowImageModel 等对象，需要把 <code>application.yaml</code> 配置文件里的 <code>yudao.ai.siliconflow</code> 配置项，替换成你的！</p><div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">yudao</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    siliconflow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 硅基流动</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      api-key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\${SILICONFLOW_API_KEY}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">deepseek-ai/DeepSeek-V4-Pro</span></span></code></pre></div><p>② 如果你希望使用 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单的密钥配置，则可以通过 AiModelService 的 <code>#getChatModel(...)</code> 或 <code>#getImageModel(...)</code> 方法，获取对应的模型对象。</p><hr><p>① 和 ② 这两者的后续使用，就是标准的 Spring AI 客户端的使用，调用对应的方法即可。</p><p>另外，SiliconFlowChatModelTests、SiliconFlowImageModelTests 里有对应的测试用例，可以参考。</p>`,29)])])}const _=a(l,[["render",d]]);export{g as __pageData,_ as default};
